templates.templateContent:
{
  "building": "{{#each elementsByClassName.Building}}{{name}}{{/each}}",
  "units": {"position": "m", "yaw": "deg"},
  "devices": [
{{resetListComma "devices"}}{{#each elementsByClassName.SmokeDetector}}{{commaIfNeeded "devices"}}
    {"deviceId": "{{deviceId}}", "type": "SmokeDetector", "room": "{{resolvedReferences.installedIn.name}}", "gateway": "{{resolvedReferences.gateway.name}}", "x": {{meters X}}, "y": {{meters Y}}, "z": {{meters Z}}, "yaw": {{#unless RZ}}0{{else}}{{RZ}}{{/unless}} }{{/each}}
{{#each elementsByClassName.MotionSensor}}{{commaIfNeeded "devices"}}
    {"deviceId": "{{deviceId}}", "type": "MotionSensor", "room": "{{resolvedReferences.installedIn.name}}", "gateway": "{{resolvedReferences.gateway.name}}", "x": {{meters X}}, "y": {{meters Y}}, "z": {{meters Z}}, "yaw": {{#unless RZ}}0{{else}}{{RZ}}{{/unless}} }{{/each}}
{{#each elementsByClassName.Camera}}{{commaIfNeeded "devices"}}
    {"deviceId": "{{deviceId}}", "type": "Camera", "room": "{{resolvedReferences.installedIn.name}}", "gateway": "{{resolvedReferences.gateway.name}}", "x": {{meters X}}, "y": {{meters Y}}, "z": {{meters Z}}, "yaw": {{#unless RZ}}0{{else}}{{RZ}}{{/unless}} }{{/each}}
{{#each elementsByClassName.Gateway}}{{commaIfNeeded "devices"}}
    {"deviceId": "{{deviceId}}", "type": "Gateway", "room": "{{resolvedReferences.installedIn.name}}", "gateway": "{{resolvedReferences.gateway.name}}", "x": {{meters X}}, "y": {{meters Y}}, "z": {{meters Z}}, "yaw": {{#unless RZ}}0{{else}}{{RZ}}{{/unless}} }{{/each}}
  ]
}
